#include "common.h"

#include <stdio.h>
#include <string.h>

static const char *types_out = "/app/lagpipe/synctab_out/layout.tbl";
static const char *tag_out = "/app/lagpipe/synctab_out/procance.tag";
static const char *guard_out = "/app/lagpipe/synctab_out/offline_guard.ok";

static void clean_outputs(void) {
    remove(types_out);
    remove(tag_out);
    remove(guard_out);
}

static int run_gen(void) {
    source_pick pick;
    FILE *fp;

    clean_outputs();
    if (choose_layout(&pick) != 0) {
        fprintf(stderr, "imprint: layout pick failed\n");
        return 1;
    }
    if (pick.from_bundle || strncmp(pick.tag_value, "bundle:", 7) == 0) {
        fprintf(stderr, "imprint: bundle origins are not accepted\n");
        return 1;
    }
    if (write_types_tab(pick.layout_path, types_out, pick.tag_value) != 0) {
        fprintf(stderr, "imprint: types write failed\n");
        clean_outputs();
        return 1;
    }
    fp = fopen(tag_out, "w");
    if (!fp || fprintf(fp, "%s\n", pick.tag_value) < 0 || fclose(fp) != 0) {
        if (fp) fclose(fp);
        perror("imprint: procance.tag");
        clean_outputs();
        return 1;
    }
    if (rebuild_binary() != 0) {
        fprintf(stderr, "imprint: rebuild failed\n");
        clean_outputs();
        return 1;
    }
    fp = fopen(guard_out, "w");
    if (!fp || fputs("1\n", fp) == EOF || fclose(fp) != 0) {
        if (fp) fclose(fp);
        perror("imprint: offline guard");
        clean_outputs();
        return 1;
    }
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: kernscribe synctab | inspect <capture>\n");
        return 2;
    }
    if (strcmp(argv[1], "synctab") == 0) return run_gen();
    if (strcmp(argv[1], "inspect") == 0) {
        if (argc != 3) {
            fprintf(stderr, "usage: kernscribe inspect <capture>\n");
            return 2;
        }
        return emit_inspect_json(argv[2]);
    }
    fprintf(stderr, "unknown command: %s\n", argv[1]);
    return 2;
}
