    for (int i = 0; i < layout.nfields; i++) {
        const field_def *f = &layout.fields[i];
        unsigned need;
        if (strcmp(f->kind, "u32") == 0 && f->size == 4) need = 4;
        else if (strcmp(f->kind, "u64") == 0 && f->size == 8) need = 8;
        else {
            fprintf(stderr, "probe: unsupported field type\n");
            return 1;
        }
        if (f->off > nread || need > nread - f->off) {
            fprintf(stderr, "probe: inspect too short\n");
            return 1;
        }
    }
    printf("{\"struct\":\"%s\"", layout.struct_name);
    for (int i = 0; i < layout.nfields; i++) {
        const field_def *f = &layout.fields[i];
        if (strcmp(f->kind, "u64") == 0)
            printf(",\"%s\":%llu", f->name,
                   (unsigned long long)read_u64_le(blob + f->off));
        else
            printf(",\"%s\":%lu", f->name,
                   (unsigned long)read_u32_le(blob + f->off));
    }
    puts("}");
    return 0;
}
